/**
 * Friend Categories API 测试
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:friend-categories-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class FriendCategoriesApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Friend Categories API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testGetCategories());
        results.push(await this.testCreateCategory());
        results.push(await this.testDeleteCategory());

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Friend Categories API Results: ${passed}/${results.length} passed`);
    }

    private async testGetCategories(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const categories = await this.client.friends.getCategories();

            return {
                name: "Get Categories",
                passed: Array.isArray(categories),
                responseTime: Date.now() - startTime,
                response: { count: categories.length },
            };
        } catch (error: any) {
            return {
                name: "Get Categories",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testCreateCategory(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const category = await this.client.friends.createCategory("Test Category");

            return {
                name: "Create Category",
                passed: category !== null && category.name === "Test Category",
                responseTime: Date.now() - startTime,
                response: { categoryId: category.id },
            };
        } catch (error: any) {
            return {
                name: "Create Category",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testDeleteCategory(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.deleteCategory("test-category");

            return {
                name: "Delete Category",
                passed: typeof result === "boolean",
                responseTime: Date.now() - startTime,
                response: { success: result },
            };
        } catch (error: any) {
            return {
                name: "Delete Category",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}

const tests = new FriendCategoriesApiTests();
tests.runAllTests().catch((error) => log.error(error));
